import{_ as o,o as a,c as n,a2 as t}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"iPhone USB 连接","description":"Mobile Inspector development documentation · iPhone USB 连接","frontmatter":{"title":"iPhone USB 连接","description":"Mobile Inspector development documentation · iPhone USB 连接"},"headers":[],"relativePath":"zh/guide/connection-usb.md","filePath":"zh/guide/connection-usb.md"}'),i={name:"zh/guide/connection-usb.md"};function r(c,e,s,d,h,l){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="iphone-usb-连接" tabindex="-1">iPhone USB 连接 <a class="header-anchor" href="#iphone-usb-连接" aria-label="Permalink to &quot;iPhone USB 连接&quot;">​</a></h1><p>USB 是 Mac 上通过 Xcode/CoreDevice 支持的有线 iPhone 流程，不要求共享 Wi-Fi，也不是 Android、HarmonyOS 或浏览器的通用 USB 传输。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>使用已连接并信任 Mac 的实体 iPhone、可传数据的线缆、Xcode 命令行工具与 OpenSSL。内部应用应已接入原生 SDK，并声明诊断本地网络用途。设备签名、安装及真实权限提示由应用维护者负责。</p><h2 id="显式配对" tabindex="-1">显式配对 <a class="header-anchor" href="#显式配对" aria-label="Permalink to &quot;显式配对&quot;">​</a></h2><p>查看器中选择 <strong>USB</strong>，选中已连接手机，再生成配对。服务端会重新确认物理有线绑定并解析路由，不接受客户端任意提供的 USB 目标地址。USB 不显示局域网二维码。</p><p>点击 <strong>复制到手机</strong>，在诊断面板粘贴并连接。复制只在点击时执行所选设备的 Xcode 剪贴板命令，不读取手机剪贴板，也不自动同步。配置时保持停止，随后独立开启记录。</p><h2 id="核对实际到达" tabindex="-1">核对实际到达 <a class="header-anchor" href="#核对实际到达" aria-label="Permalink to &quot;核对实际到达&quot;">​</a></h2><p>触发一次无敏感内容的内部测试操作，确认事件到达查看器且属于预期会话。发现设备、复制成功或面板已配置，都不能单独证明传输到达。</p><p>拔线后应停止并重新选择有效设备，不能依据旧选择器推断身份。优先检查信任、线缆与 Xcode，再考虑网络设置。<a href="./connection-lan">局域网与手工配对</a>是独立备用路径。</p>',10)])])}const _=o(i,[["render",r]]);export{u as __pageData,_ as default};
